{
  "items": [
    {
      "name": "ENNReal.rpow_arith_mean_le_arith_mean2_rpow",
      "module_name": "Mathlib.Analysis.MeanInequalitiesPow",
      "kind": "theorem",
      "type": "∀ (w₁ w₂ z₁ z₂ : ENNReal), w₁ + w₂ = 1 → ∀ {p : ℝ}, 1 ≤ p → (w₁ * z₁ + w₂ * z₂) ^ p ≤ w₁ * z₁ ^ p + w₂ * z₂ ^ p"
    },
    {
      "name": "Real.pow_arith_mean_le_arith_mean_pow",
      "module_name": "Mathlib.Analysis.MeanInequalitiesPow",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → ℝ),\n  (∀ i ∈ s, 0 ≤ w i) →\n    ∑ i ∈ s, w i = 1 → (∀ i ∈ s, 0 ≤ z i) → ∀ (n : ℕ), (∑ i ∈ s, w i * z i) ^ n ≤ ∑ i ∈ s, w i * z i ^ n"
    },
    {
      "name": "ENNReal.rpow_arith_mean_le_arith_mean_rpow",
      "module_name": "Mathlib.Analysis.MeanInequalitiesPow",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → ENNReal),\n  ∑ i ∈ s, w i = 1 → ∀ {p : ℝ}, 1 ≤ p → (∑ i ∈ s, w i * z i) ^ p ≤ ∑ i ∈ s, w i * z i ^ p"
    },
    {
      "name": "Real.rpow_of_add_eq",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {w x y z : ℝ}, 0 ≤ x → w ≠ 0 → y + z = w → x ^ w = x ^ y * x ^ z"
    },
    {
      "name": "NNReal.rpow_arith_mean_le_arith_mean2_rpow",
      "module_name": "Mathlib.Analysis.MeanInequalitiesPow",
      "kind": "theorem",
      "type": "∀ (w₁ w₂ z₁ z₂ : NNReal), w₁ + w₂ = 1 → ∀ {p : ℝ}, 1 ≤ p → (w₁ * z₁ + w₂ * z₂) ^ p ≤ w₁ * z₁ ^ p + w₂ * z₂ ^ p"
    },
    {
      "name": "NNReal.arith_mean_le_rpow_mean",
      "module_name": "Mathlib.Analysis.MeanInequalitiesPow",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → NNReal),\n  ∑ i ∈ s, w i = 1 → ∀ {p : ℝ}, 1 ≤ p → ∑ i ∈ s, w i * z i ≤ (∑ i ∈ s, w i * z i ^ p) ^ (1 / p)"
    },
    {
      "name": "Real.arith_mean_le_rpow_mean",
      "module_name": "Mathlib.Analysis.MeanInequalitiesPow",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → ℝ),\n  (∀ i ∈ s, 0 ≤ w i) →\n    ∑ i ∈ s, w i = 1 → (∀ i ∈ s, 0 ≤ z i) → ∀ {p : ℝ}, 1 ≤ p → ∑ i ∈ s, w i * z i ≤ (∑ i ∈ s, w i * z i ^ p) ^ (1 / p)"
    },
    {
      "name": "NNReal.geom_mean_le_arith_mean_weighted",
      "module_name": "Mathlib.Analysis.MeanInequalities",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → NNReal), ∑ i ∈ s, w i = 1 → ∏ i ∈ s, z i ^ ↑(w i) ≤ ∑ i ∈ s, w i * z i"
    }
  ]
}
